\set ON_ERROR_STOP on
begin;
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end $$;
create function pg_temp.denied(command text,label text) returns void language plpgsql as $$ begin begin execute command;exception when others then raise notice 'PASS denied: %',label;return;end;raise exception 'FAIL allowed: %',label;end $$;
insert into auth.users values('00000000-0000-0000-0000-000000000001'),('00000000-0000-0000-0000-000000000002'),('00000000-0000-0000-0000-000000000003');
insert into moderators values('00000000-0000-0000-0000-000000000003');
select set_config('test.payload',jsonb_build_object('category','Travel','kind','road','title','Synthetic retry fixture','description','','latitude',61.2181,'longitude',-149.9003,'place_name','Synthetic trail','observed_at',now(),'details','{}'::jsonb,'extent',null,'taxonomy_version',2,'domain_id','travel','topic_id','travel.surface','event_type_id','black_ice','related_type_ids','[]'::jsonb,'answers','{}'::jsonb)::text,true);
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select set_config('test.id',(select id::text from submit_observation('11111111-1111-4111-8111-111111111111',current_setting('test.payload')::jsonb)),true);
select pg_temp.assert_true((select count(*)=1 from observations),'first save creates one observation');
select pg_temp.assert_true((select id=current_setting('test.id')::uuid from submit_observation('11111111-1111-4111-8111-111111111111',current_setting('test.payload')::jsonb)),'retry returns the original observation id');
select pg_temp.assert_true((select count(*)=1 from observations),'retry does not create a duplicate');
select pg_temp.assert_true((select latitude=61.22 and longitude=-149.90 and expires_at=observed_at+interval '24 hours' from observations),'normal privacy and expiry triggers run');
select pg_temp.denied($q$select submit_observation('11111111-1111-4111-8111-111111111111',current_setting('test.payload')::jsonb||'{"description":"Different content"}'::jsonb)$q$,'a request cannot be repurposed with different content');
select pg_temp.denied($q$select submit_observation('22222222-2222-4222-8222-222222222222',current_setting('test.payload')::jsonb||'{"author_id":"00000000-0000-0000-0000-000000000002"}'::jsonb)$q$,'cannot inject another author');
select pg_temp.denied($q$select submit_observation('22222222-2222-4222-8222-222222222222',current_setting('test.payload')::jsonb||'{"status":"published","verification":"reviewed"}'::jsonb)$q$,'cannot inject moderation fields');
select pg_temp.denied($q$select submit_observation('22222222-2222-4222-8222-222222222222',current_setting('test.payload')::jsonb||'{"expires_at":"2099-01-01"}'::jsonb)$q$,'cannot inject expiry');
select pg_temp.denied($q$select submit_observation('22222222-2222-4222-8222-222222222222',current_setting('test.payload')::jsonb||'{"answers":{"snow_surface":"powder"}}'::jsonb)$q$,'unrelated answers are still rejected');
select pg_temp.denied($q$select * from observation_submissions$q$,'receipt ledger is not directly readable');
select pg_temp.denied($q$insert into observation_submissions values(auth.uid(),'22222222-2222-4222-8222-222222222222','forged',null,now())$q$,'receipt ledger is not directly writable');
select pg_temp.assert_true((select status='review' from submit_observation('33333333-3333-4333-8333-333333333333',current_setting('test.payload')::jsonb||'{"domain_id":"safety","topic_id":"safety.public","event_type_id":"gunfire_heard","title":"Synthetic private fixture"}')),'sensitive observations still enter private review');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select pg_temp.assert_true((select id<>current_setting('test.id')::uuid from submit_observation('11111111-1111-4111-8111-111111111111',current_setting('test.payload')::jsonb)),'request keys are scoped to the current actor');
reset role;
select pg_temp.assert_true((select count(*)=3 from observation_submissions),'only successful unique saves have receipts');
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select pg_temp.denied($q$select submit_observation('11111111-1111-4111-8111-111111111111',current_setting('test.payload')::jsonb)$q$,'anonymous save execution denied');
select pg_temp.denied($q$select * from observation_submissions$q$,'anonymous receipt access denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
select moderate_report(current_setting('test.id')::uuid,'hide','Synthetic moderation test');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select pg_temp.assert_true((select status='hidden' from submit_observation('11111111-1111-4111-8111-111111111111',current_setting('test.payload')::jsonb)),'retry reflects moderation without republishing');
select set_config('test.deleted',(select id::text from submit_observation('44444444-4444-4444-8444-444444444444',current_setting('test.payload')::jsonb)),true);
reset role;
-- Removing the observation retains a tombstone receipt, never recreates it.
delete from observations where id=current_setting('test.deleted')::uuid;
select pg_temp.assert_true((select observation_id is null from observation_submissions where user_id='00000000-0000-0000-0000-000000000001' and request_id='44444444-4444-4444-8444-444444444444'),'deleted observation keeps its receipt tombstone');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select pg_temp.denied($q$select submit_observation('44444444-4444-4444-8444-444444444444',current_setting('test.payload')::jsonb)$q$,'retry cannot resurrect a removed observation');
reset role;
select pg_temp.assert_true((select count(*)=3 from observations),'failed and replayed saves leave other observations intact');
rollback;
